class CreateExpensesAndAllocations < ActiveRecord::Migration[8.1]
  # Core expense entity + per-branch allocation rows for shared expenses.
  #
  # branch_id is nullable: NULL = a shared / business-level expense whose cost is
  # split across branches via expense_allocations (Σ allocation_percentage = 100,
  # enforced at the model layer). A present branch_id = the whole amount belongs
  # to one branch.
  #
  # reference_number is the per-business sequential document number (EXP-000001),
  # generated by Finance::NumberSequencer. source_recurring_expense_id is added in
  # a later migration (after recurring_expenses exists).
  def change
    create_table :expenses do |t|
      t.references :business,         null: false, foreign_key: true
      t.references :branch,           foreign_key: true
      t.references :expense_category, null: false, foreign_key: true
      t.references :expense_type,     foreign_key: true

      t.decimal :amount, precision: 12, scale: 2, null: false
      t.date    :expense_date, null: false
      t.text    :description
      t.string  :reference_number, null: false
      t.string  :vendor_name
      t.string  :status, null: false, default: "draft"
      t.text    :notes
      t.boolean :is_shared, null: false, default: false

      t.references :created_by, foreign_key: { to_table: :users }
      t.references :approved_by, foreign_key: { to_table: :users }
      t.datetime   :approved_at
      t.references :paid_by, foreign_key: { to_table: :users }
      t.datetime   :paid_at
      t.datetime   :rejected_at
      t.text       :rejection_reason

      t.timestamps
    end
    add_index :expenses, [ :business_id, :reference_number ], unique: true
    add_index :expenses, [ :business_id, :status ]
    add_index :expenses, [ :business_id, :expense_date ]

    create_table :expense_allocations do |t|
      t.references :expense, null: false, foreign_key: true
      t.references :branch,  null: false, foreign_key: true
      t.decimal :allocation_percentage, precision: 5,  scale: 2, null: false, default: 0
      t.decimal :allocated_amount,      precision: 12, scale: 2, null: false, default: 0
      t.timestamps
    end
    add_index :expense_allocations, [ :expense_id, :branch_id ], unique: true

    create_table :expense_taggings do |t|
      t.references :expense,     null: false, foreign_key: true
      t.references :expense_tag, null: false, foreign_key: true
      t.timestamps
    end
    add_index :expense_taggings, [ :expense_id, :expense_tag_id ], unique: true
  end
end
